  "implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'threshold' not in case or 'calls' not in case:
        raise ValueError("case must contain 'threshold' and 'calls'")
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    required_fields = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
    diagnostics = []
    accepted_call_ids = []
    for i, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f"calls[{i}] must be a dict")
        for field in required_fields:
            if field not in call:
                raise ValueError(f"calls[{i}] missing field '{field}'")
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        pred_tokens = call['prediction_tokens']
        parseable = call['parseable']
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError(f"calls[{i}] loss values must be numbers")
        if not isinstance(pred_tokens, int) or pred_tokens < 1:
            raise ValueError(f"calls[{i}] prediction_tokens must be positive integer")
        if not isinstance(parseable, bool):
            raise ValueError(f"calls[{i}] parseable must be bool")
        gain = loss_without - loss_with
        normalized_gain = gain / max(pred_tokens, 1)
        accepted = parseable and normalized_gain >= threshold
        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append({
            'call_id': call_id,
            'gain': round(gain, 6),
            'normalized_gain': round(normalized_gain, 6),
            'parseable': parseable,
            'accepted': accepted
        })
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"
}
